      },
      {
        "aspectIndex": 24,
        "criterionId": "q9",
        "earned": true,
        "quote": "A contribuição brasileira para o esforço de guerra aliado foi significativa."
      },
      {
        "aspectIndex": 25,
        "criterionId": "q9",
        "earned": true,
        "quote": "o Brasil enviou uma missão de enfermeiros para o front e uma missão de aviadores para treinar com a Grã-Bretanha."
      },
      {
